      w: [['beach', 'plyaj', 'пляж', 'noun', 'The beach is very clean.', 'Plyaj juda toza.', 'biːtʃ'], ['mountain', 'tog‘', 'гора', 'noun', 'We climbed a high mountain.', 'Biz baland tog‘ga chiqdik.', 'ˈmaʊntən'], ['island', 'orol', 'остров', 'noun', 'The island is small.', 'Orol kichik.', 'ˈaɪlənd'], ['sightseeing', 'diqqatga sazovor joylarni ko‘rish', 'осмотр достопримечательностей', 'noun', 'We went sightseeing in Rome.', 'Biz Rimda ko‘rgazmali joylarni ko‘rdik.', 'ˈsaɪtsiːɪŋ'], ['tourist', 'sayyoh', 'турист', 'noun', 'Many tourists visit Samarkand.', 'Ko‘p sayyohlar Samarqandga keladi.', 'ˈtʊərɪst'], ['countryside', 'qishloq joy', 'сельская местность', 'noun', 'I love the quiet countryside.', 'Men tinch qishloq joyni yaxshi ko‘raman.', 'ˈkʌntrisaɪd']],
