      w: [['check-in', 'ro‘yxatdan o‘tish', 'регистрация', 'noun', 'Check-in opens at six.', 'Ro‘yxatdan o‘tish oltida boshlanadi.', 'ˈtʃek ɪn'], ['boarding pass', 'chiqish taloni', 'посадочный талон', 'noun', 'Show your boarding pass.', 'Chiqish talonini ko‘rsating.', 'ˈbɔːdɪŋ pɑːs'], ['departure', 'jo‘nash', 'вылет', 'noun', 'The departure is at ten.', 'Jo‘nash soat o‘nda.', 'dɪˈpɑːtʃə'], ['arrival', 'kelish', 'прибытие', 'noun', 'The arrival time is noon.', 'Kelish vaqti tush.', 'əˈraɪvl'], ['security', 'xavfsizlik tekshiruvi', 'досмотр', 'noun', 'Security takes ten minutes.', 'Tekshiruv o‘n daqiqa oladi.', 'sɪˈkjʊərəti'], ['delay', 'kechikish', 'задержка', 'noun', 'There is a delay of one hour.', 'Bir soatlik kechikish bor.', 'dɪˈleɪ']],
